     and s.menu_path = #{menuPath}
     and s.link_re_meta_model_id = #{linkReMetaModelId}
     and s.link_re_meta_model = #{linkReMetaModel}
     and s.link_re_meta_model_cn = #{linkReMetaModelCn}
     and s.link_re_column_id = #{linkReColumnId}
     and s.link_re_column_name like concat('%', #{linkReColumnName}, '%')
